<style>
.xd323-page .xd323-project-detail{background:#f5f8f4;padding:36px 0 72px}
.xd323-project-breadcrumb{display:flex;flex-wrap:wrap;gap:10px;margin-bottom:24px;color:#647369;font-size:14px;line-height:1.6;overflow-wrap:anywhere}
