.xd323-project-cover{width:100%;height:100%;min-height:360px;max-height:500px;object-fit:cover;display:block}
.xd323-project-body{padding:40px 48px;max-width:1080px}
.xd323-project-body-title{margin:0 0 24px;color:#063e30;font-size:26px}
.xd323-project-detail .xd-rich-content{color:#4c5d53;line-height:1.85;font-size:17px}
.xd323-project-detail .xd-rich-content h2,.xd323-project-detail .xd-rich-content h3{color:#244c35;line-height:1.4;margin:28px 0 12px}
.xd323-project-gallery{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px;padding:0 48px 40px}
.xd323-project-gallery figure{margin:0}.xd323-project-gallery img{display:block;width:100%;height:280px;object-fit:cover;border-radius:10px}
